SELECT c.relname AS table_name, has_table_privilege('anon', c.oid, 'SELECT') AS anon_can_read, has_table_privilege('anon', c.oid, 'INSERT') AS anon_can_add, has_table_privilege('anon', c.oid, 'UPDATE') AS anon_can_change, has_table_privilege('anon', c.oid, 'DELETE') AS anon_can_delete, has_any_column_privilege('anon', c.oid, 'SELECT') AS anon_can_read_any_column, has_table_privilege('authenticated', c.oid, 'SELECT') AS signed_in_can_read, has_table_privilege('authenticated', c.oid, 'INSERT') AS signed_in_can_add, has_table_privilege('service_role', c.oid, 'SELECT') AS server_can_read, has_table_privilege('service_role', c.oid, 'UPDATE') AS server_can_change FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relname IN ('bank_transactions', 'egypt_bank_transactions', 'egypt_bank_accounts', 'egypt_bank_rules', 'module_permissions', 'open_accounts', 'open_account_entries', 'open_account_invoices', 'open_account_invoice_items', 'warehouse_advances', 'fx_rates', 'inventory_landed_costs', 'inventory_layers', 'attachments') ORDER BY 1;
